package it.penny.api.products;
import it.penny.api.security.*;
import it.penny.api.common.AuditLog;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.*;
@RestController public class ProductTaxonomyController{
 private final JdbcTemplate db;private final PennyUserRepository users;private final RbacService rbac;private final AuditLog audit;
 public ProductTaxonomyController(JdbcTemplate db,PennyUserRepository users,RbacService rbac,AuditLog audit){this.db=db;this.users=users;this.rbac=rbac;this.audit=audit;}
 private void require(Authentication auth,String p){rbac.require(auth==null?null:users.findByEmailIgnoreCase(auth.getName()).orElse(null),p);}
 public record CategoryInput(String name,String operationalKind,Boolean active){}
 public record TypeInput(Long categoryId,String name,Boolean obsolete){}
 private static final String CATEGORY_FIELDS="id,code,name,operational_kind AS \"operationalKind\",legacy_category AS \"legacyCategory\",active,is_system AS \"isSystem\"";
 @GetMapping("/api/product-categories") public Map<String,Object> categories(@RequestParam(required=false) Boolean active,Authentication auth){require(auth,"CATALOG_READ");var items=db.queryForList("SELECT "+CATEGORY_FIELDS+" FROM penny_product_categories WHERE (CAST(? AS boolean) IS NULL OR active=?) ORDER BY lower(name),id",active,active);return Map.of("items",items,"total",items.size());}
 @PostMapping("/api/product-categories") @Transactional public Map<String,Object> createCategory(@RequestBody CategoryInput in,Authentication auth){require(auth,"CATALOG_WRITE");var kind=kind(in.operationalKind());long id=db.queryForObject("INSERT INTO penny_product_categories(code,name,operational_kind,legacy_category,active) VALUES (?,?,?,?,?) RETURNING id",Long.class,"CUSTOM-"+UUID.randomUUID().toString().substring(0,12),CatalogProductController.required(in.name(),160,"Nome categoria"),kind,Set.of("CONTRACT","OTHER").contains(kind)?"SERVICE":kind,!Boolean.FALSE.equals(in.active()));audit.record(auth,"CATEGORY_CREATED","PRODUCT_CATEGORY",id,Map.of());return Map.of("id",id);}
 @PutMapping("/api/product-categories/{id}") @Transactional public Map<String,Object> updateCategory(@PathVariable long id,@RequestBody CategoryInput in,Authentication auth){require(auth,"CATALOG_WRITE");var old=db.queryForList("SELECT operational_kind FROM penny_product_categories WHERE id=? FOR UPDATE",id);if(old.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Categoria non trovata");if(in.operationalKind()!=null&&!old.getFirst().get("operational_kind").equals(kind(in.operationalKind())))throw CatalogProductController.bad("La famiglia operativa non può cambiare; crea una nuova categoria");db.update("UPDATE penny_product_categories SET name=?,active=? WHERE id=?",CatalogProductController.required(in.name(),160,"Nome categoria"),!Boolean.FALSE.equals(in.active()),id);audit.record(auth,"CATEGORY_UPDATED","PRODUCT_CATEGORY",id,Map.of());return Map.of("updated",true);}
 private String kind(String value){if(!Set.of("HARDWARE","SOFTWARE","TRAINING","CONTRACT","OTHER").contains(value==null?"":value))throw CatalogProductController.bad("Famiglia operativa non valida");return value;}
 @GetMapping("/api/product-types") public Map<String,Object> types(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page,@RequestParam(required=false) Integer size,@RequestParam(required=false) Long categoryId,@RequestParam(required=false) String operationalKind,@RequestParam(required=false) Boolean obsolete,Authentication auth){require(auth,"CATALOG_READ");if(operationalKind!=null)kind(operationalKind);if(size!=null)CatalogProductController.pagination(page,size);String search=CatalogProductController.like(q);var items=db.queryForList("SELECT t.id,t.category_id AS \"categoryId\",t.name,t.obsolete,t.is_system AS \"isSystem\",c.name AS \"categoryName\",c.operational_kind AS \"operationalKind\" FROM penny_product_types t JOIN penny_product_categories c ON c.id=t.category_id WHERE (CAST(? AS bigint) IS NULL OR t.category_id=?) AND (CAST(? AS varchar) IS NULL OR c.operational_kind=?) AND (CAST(? AS boolean) IS NULL OR t.obsolete=?) AND (lower(t.name) LIKE ? OR lower(c.name) LIKE ?) ORDER BY lower(t.name),t.id",categoryId,categoryId,operationalKind,operationalKind,obsolete,obsolete,search,search);int total=items.size();if(size!=null){int offset=Math.min(total,page*size);items=items.subList(offset,Math.min(total,offset+size));}return Map.of("items",items,"total",total);}
 @PostMapping("/api/product-types") @Transactional public Map<String,Object> createType(@RequestBody TypeInput in,Authentication auth){require(auth,"CATALOG_WRITE");category(in.categoryId());long id=db.queryForObject("INSERT INTO penny_product_types(category_id,name,obsolete) VALUES (?,?,?) RETURNING id",Long.class,in.categoryId(),CatalogProductController.required(in.name(),160,"Nome tipologia"),Boolean.TRUE.equals(in.obsolete()));audit.record(auth,"TYPE_CREATED","PRODUCT_TYPE",id,Map.of());return Map.of("id",id);}
 private void category(Long id){if(id==null||db.queryForList("SELECT id FROM penny_product_categories WHERE id=? FOR SHARE",id).isEmpty())throw CatalogProductController.bad("Categoria non disponibile");}
 @PutMapping("/api/product-types/{id}") @Transactional public Map<String,Object> updateType(@PathVariable long id,@RequestBody TypeInput in,Authentication auth){require(auth,"CATALOG_WRITE");var old=db.queryForList("SELECT category_id FROM penny_product_types WHERE id=? FOR UPDATE",id);if(old.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Tipologia non trovata");if(in.categoryId()!=null&&!old.getFirst().get("category_id").equals(in.categoryId()))throw CatalogProductController.bad("La tipologia non può cambiare categoria");db.update("UPDATE penny_product_types SET name=?,obsolete=? WHERE id=?",CatalogProductController.required(in.name(),160,"Nome tipologia"),Boolean.TRUE.equals(in.obsolete()),id);audit.record(auth,"TYPE_UPDATED","PRODUCT_TYPE",id,Map.of());return Map.of("updated",true);}
}
